using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Export;
public sealed class FiveMResourceBuilder { public string Prepare(ShellProject p,string output,string? gtaStreamSource=null){var safe=string.Concat(p.Name.ToLowerInvariant().Select(c=>char.IsLetterOrDigit(c)||c=='_'?c:'_')).Trim('_');if(string.IsNullOrWhiteSpace(safe))safe="tonecustoms_shell";var root=Path.Combine(output,safe);var stream=Path.Combine(root,"stream");Directory.CreateDirectory(stream);if(!string.IsNullOrWhiteSpace(gtaStreamSource)&&Directory.Exists(gtaStreamSource))foreach(var f in Directory.GetFiles(gtaStreamSource))File.Copy(f,Path.Combine(stream,Path.GetFileName(f)),true);File.WriteAllText(Path.Combine(root,"fxmanifest.lua"),"fx_version 'cerulean'\ngame 'gta5'\nthis_is_a_map 'yes'\n");File.WriteAllText(Path.Combine(root,"shellstudio.json"),System.Text.Json.JsonSerializer.Serialize(p,new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));return root;} }
